import re
from pathlib import Path

SUPPORTED = {'.png', '.jpg', '.jpeg'}


def include(path):
    return Path(str(path)).suffix.lower() in SUPPORTED


def label_for(path):
    stem = Path(str(path)).stem
    return re.sub(r'_\d+x\d+$', '', stem, flags=re.IGNORECASE)


def row_for(path, width, height):
    return {
        'file': path,
        'width': width,
        'height': height,
        'label': label_for(path),
    }
